const d = pm.iterationData;
const body = {
  firstname: d.get("firstname"),
  lastname: d.get("lastname"),
  totalprice: Number(d.get("totalprice")),
  depositpaid: d.get("depositpaid") === "true",
  bookingdates: { checkin: d.get("checkin"), checkout: d.get("checkout") },
  additionalneeds: d.get("additionalneeds")
};
pm.variables.set("requestBody", JSON.stringify(body));

const d = pm.iterationData;
const expected = Number(d.get("expected_status"));
const label = `[${d.get("category")}] row ${pm.info.iteration + 1}`;

pm.test(`${label}: status is ${expected}`, () => {
  pm.response.to.have.status(expected);
});

pm.test(`${label}: no server error`, () => {
  pm.expect(pm.response.code).to.be.below(500);
});

if (pm.response.code === 200) {
  const res = pm.response.json();
  pm.test(`${label}: data stored exactly as sent`, () => {
    pm.expect(res.booking.firstname).to.eql(d.get("firstname"));
    pm.expect(res.booking.additionalneeds).to.eql(d.get("additionalneeds"));
  });
}
